mapper.select:
SELECT COUNT(*) FROM dispute_ticket d
                    JOIN shopping_session s ON d.session_id = s.session_id
                    WHERE d.status = 'OPEN' AND s.device_id IN #{__item}


SELECT COUNT(*) FROM dispute_ticket d
                    WHERE d.status = 'OPEN' AND d.sla_due_at IS NOT NULL
                      AND d.sla_due_at >= #{now} AND d.sla_due_at <= #{threshold}


SELECT COUNT(*) FROM dispute_ticket d
                    WHERE d.status = 'RESOLVED' AND d.resolved_at >= #{since}
                      AND (d.sla_due_at IS NULL OR d.resolved_at <= d.sla_due_at)
